assert("Live.create() の初期値が正しい", Live.get(lc1) === 10);
// ─── 3. lf_sub : 登録直後の即時通知 ──────────────────────────────────────────
section("3. lf_sub : 登録直後の即時通知");
const lf4 = new Live.Leaf(10);
