assert("set 後の vchan 値が新しい値と一致する", ref1.values[1] === 20);
assert("lv_get() が新しい値を返す", lf4[lv_get]() === 20);
assert("Live.get() も新しい値を返す", Live.get(lf4) === 20);
// ─── 5. 同値再セット時は通知しない ───────────────────────────────────────────
